var t=`1041-gado-gado`;var n=`world-1041`;var a=`ID`;var s=`southeast-asia`;var o=4;var r=50;var g={en:`Gado-Gado`,ua:`Гадо-гадо`};var u={en:`Gado-Gado is a dish from Indonesia prepared with potato, green beans, tofu (firm), mung bean sprouts. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Гадо-гадо, страва кухні країни Індонезія, яку готують із таких продуктів: картопля, стручкова квасоля, твердий тофу, проростки машу. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 20 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 20 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:20,i:[[`potato`,400,`g`],[`green-beans`,250,`g`],[`water`,900,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 8 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 8 хвилин до готовності й м’якості.`,t:[`poaching`],m:8,i:[[`tofu-firm`,280,`g`],[`mung-bean-sprouts`,190,`g`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 8 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 8 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:8,i:[[`peanut-butter`,190,`g`],[`coconut-milk`,190,`ml`],[`tamarind-concentrate`,28,`g`],[`palm-sugar`,30,`g`],[`garlic`,3,`clove`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`cucumber`,170,`g`],[`white-cabbage`,170,`g`]]}];var l={slug:t,id:n,country:`ID`,region:s,servings:4,minutes:50,title:g,text:u,steps:d};export{a as country,l as default,n as id,r as minutes,s as region,o as servings,t as slug,d as steps,u as text,g as title};